#!/usr/bin/env python
"""Regenerate the auto-generated status block in HANDOFF.md (plan Step 0.2; D2 deferred it).

Only the text between ``<!-- AUTO:status BEGIN -->`` and ``<!-- AUTO:status END -->``
is rewritten; everything else in HANDOFF.md is hand-written judgement and is
never touched. The block lists, without reading any result value:

* each ``results/<stage>/run.manifest.json``: commit, dirty flag, start time;
* progress of the long data jobs (feature caches, later-progression transports,
  round-trip study, PDE frames), as counts of finished units;
* the ten most recent commits.

As a git pre-commit hook (``scripts/install_hooks.py``) it runs before each
commit and stages HANDOFF.md, so the commit table lags by one entry.

    python scripts/update_handoff.py
"""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]
HANDOFF = REPO_ROOT / "HANDOFF.md"
BEGIN, END = "<!-- AUTO:status BEGIN -->", "<!-- AUTO:status END -->"


def _git(*args: str) -> str:
    out = subprocess.run(["git", "-C", str(REPO_ROOT), *args], capture_output=True, text=True)
    return out.stdout.strip()


def block() -> str:
    lines = [BEGIN, "", "_Auto-generated by `scripts/update_handoff.py`; do not edit inside._", ""]
    lines += [
        "### Results on disk",
        "",
        "| Stage | Commit | Dirty | Started (UTC) |",
        "|---|---|---|---|",
    ]
    manifests = sorted((REPO_ROOT / "results").glob("**/run.manifest.json"))
    for m in manifests:
        d = json.loads(m.read_text(encoding="utf-8"))
        git = d.get("git", {})
        lines.append(
            f"| `{m.parent.relative_to(REPO_ROOT).as_posix()}` | "
            f"`{(git.get('commit') or '?')[:7]}` | {git.get('dirty')} | "
            f"{d.get('started_utc', '?')} |"
        )
    if not manifests:
        lines.append("| (none) | | | |")
    interim = REPO_ROOT / "data" / "interim"
    count = lambda pattern: len(list(interim.glob(pattern)))  # noqa: E731
    lines += [
        "",
        "### Long jobs (finished units)",
        "",
        f"- LUMIERE feature caches: {count('features/*.npz')} of 63",
        f"- Later-progression transports: {count('label_field_later/*/*/qc.json')} of 83",
        f"- Round-trip threshold study: {count('roundtrip_tuned/*/qc.json')} of 63",
        f"- PDE frame sets: {count('pde_frames/*.npz')}",
        f"- RHUH-GBM transports: {count('rhuh/label_field_tuned/*/qc.json')}",
        "",
        "### Recent commits",
        "",
        "```",
        _git("log", "--oneline", "-10") or "(none)",
        "```",
        "",
        END,
    ]
    return "\n".join(lines)


def main() -> int:
    text = HANDOFF.read_text(encoding="utf-8")
    new = block()
    if BEGIN in text and END in text:
        start, stop = text.index(BEGIN), text.index(END) + len(END)
        text = text[:start] + new + text[stop:]
    else:
        text = text.rstrip() + "\n\n## Auto-generated status\n\n" + new + "\n"
    HANDOFF.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
